def countKConstraintSubstrings(s: str, k: int) -> int:
    n = len(s)
    count = 0
    # Loop through all possible starting positions
    for i in range(n):
        zeros = 0
        ones = 0
        # Expand the substring ending at j
        for j in range(i, n):
            if s[j] == '0':
                zeros += 1
            else:
                ones += 1
            # If both counts are above k, break early
            if zeros > k and ones > k:
                break
            count += 1
    return count
